/// The release identities `callisto version` has pending work for that a release would cover: publishable packages
/// only, narrowed and group-expanded by `selections` through the same code the release roster uses. Changesets only:
/// commit inference would add a git process per package to a read-only hint.
///
/// # Errors
///
/// The version plan cannot be derived.
pub fn pending_version_work<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selections: &[ReleasePackageId],
) -> Result<Vec<ReleasePackageId>, GraphError> {
    let options = super::VersionOptions {
        strict: false,
        allow_empty_changesets: true,
    };
    let plan = super::plan_version(workspace, &crate::infer::NoInference, &options)?;
    if plan.bumps.is_empty() {
        return Ok(Vec::new());
    }
    let owners = ReleaseOwners::of(workspace);
    let mut entries = derive_release_decision(workspace, &plan)?.entries;
    entries.retain(|entry| owners.get(&entry.package).is_some_and(Package::is_release_point));
    if !selections.is_empty() {
        entries = expand_selection(workspace, &owners, entries, &selections.iter().collect());
    }
    Ok(entries.into_iter().map(|entry| entry.package).collect())
}

