    interactive: bool,
    prompter: &mut dyn Prompter,
    out: &'a mut dyn Write,
    err: &'a mut dyn Write,
    runner: &R,
) -> Result<ExitCode, CliError> {
    validate_flags(&args)?;
    // A repository whose manifests all sit in subdirectories has no root yet: init makes the Git toplevel one.
