fn init(root: &Path, format: &str, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_callisto"))
        .args(["--format", format, "--cwd", root.to_str().unwrap(), "init"])
        .args(args)
        .stdin(Stdio::null())
        .output()
        .expect("callisto binary should be invocable")
}

fn both(output: &Output) -> String {
