        for diagnostic in &plan.diagnostics {
            writeln!(err, "warning: {}", diagnostic.message)?;
        }
    }
    if let Some(note) = pending_version_diagnostic(pending) {
        writeln!(err, "note: {}", note.message)?;
    }
    Ok(())
}

