    }

    /// A real release: only a hosted remote.
    pub(crate) fn required(self) -> Result<PreparedGitRemote, GraphError> {
        self.optional()?.ok_or(GraphError::UnsafeGitRemote {
            refusal: OriginRefusal::NoPushUrl,
